import { Client } from '@elastic/elasticsearch';

interface Product {
  id: string;
  name: string;
  price: number;
  description: string;
}

declare function loadAllProducts(): Promise<Product[]>;

const esClient = new Client({ node: 'http://localhost:9200' });

async function backfillProducts(): Promise<void> {
  // Pull the full source dataset into memory up front (~50,000 products).
  const products = await loadAllProducts();

  for (const product of products) {
    // One HTTP round-trip to Elasticsearch per product, forcing a
    // synchronous refresh on every single write during the backfill.
    await esClient.index({
      index: 'products',
      id: product.id,
      document: product,
      refresh: true,
    });
  }

  console.log('done');
}

backfillProducts();
